import{_ as t,o as r,c as i,a5 as a}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"模板index.html条件加载script","description":"如果你想根据当前页面的 URL 来加载特定的 JavaScript 文件，你可以使用 Vue 的动态导入 (Dynamic Import)，结合条件语句来实现。下面是一个示例： \\\\<script\\\\ // 获取当前页面的 URL const currentUrl window.lo。","frontmatter":{"title":"模板index.html条件加载script","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","项目实战"],"description":"如果你想根据当前页面的 URL 来加载特定的 JavaScript 文件，你可以使用 Vue 的动态导入 (Dynamic Import)，结合条件语句来实现。下面是一个示例： \\\\<script\\\\ // 获取当前页面的 URL const currentUrl window.lo。","sidebarWeight":68,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/实战/模板index.html条件加载script.md"},"headers":[],"relativePath":"posts/Vue系统教程/07-项目实战/模板index.html条件加载script.md","filePath":"posts/Vue系统教程/07-项目实战/模板index.html条件加载script.md"}'),s={name:"posts/Vue系统教程/07-项目实战/模板index.html条件加载script.md"};function o(p,e,c,n,l,d){return r(),i("div",null,[...e[0]||(e[0]=[a('<div><h1 id="模板index-html条件加载script" tabindex="-1">模板index.html条件加载script <a class="header-anchor" href="#模板index-html条件加载script" aria-label="Permalink to &quot;模板index.html条件加载script&quot;">​</a></h1><blockquote><p>本节目标：理解“模板index.html条件加载script”的核心思路，并能把它用于实际开发或面试表达。 如果你想根据当前页面的 URL 来加载特定的 JavaScript 文件，你可以使用 Vue 的动态导入 (Dynamic Import)，结合条件语句来实现。下面是一个示例：</p></blockquote><p>&lt;script&gt; // 获取当前页面的 URL const currentUrl = window.location.href; // 判断当前页面的 URL 是否为特定地址，然后根据条件动态加载相应的 JavaScript 文件 if (currentUrl.includes(&#39;特定地址&#39;)) { import(&#39;/static/WSPlayer/PlayerControl.js&#39;).then(module =&gt; { // 加载 PlayerControl.js 文件 // 这里可以根据需要执行一些初始化操作 }); import(&#39;/static/WSPlayer/WSPlayer.js&#39;).then(module =&gt; { // 加载 WSPlayer.js 文件 // 这里可以根据需要执行一些初始化操作 }); } &lt;/script&gt;</p><p>上述代码中，<code>特定地址</code> 是你想要判断的特定页面的 URL。如果当前页面的 URL 包含该特定地址，就会动态加载 <code>PlayerControl.js</code> 和 <code>WSPlayer.js</code> 这两个文件。</p><p>请注意，动态导入是异步的，因此在加载完 JavaScript 文件后，你可以在 <code>then</code> 方法中执行一些初始化操作，例如调用 JavaScript 文件中的函数等。</p><p>另外，请确保 <code>window.location.href</code> 返回的是你所期望的 URL 地址，因为有时候会包含一些额外的参数或者锚点等。</p><p><strong>服务器配合</strong> 这种方式就是为特定的路由单独生成一个vue项目，用来处理文件的预览； 如果你的前端文件是预先打包好的，并且希望在服务器端根据路径名加载不同的 JavaScript 文件，你可以考虑在服务器端根据请求的路径名动态生成 HTML 页面。这可以通过在服务器端的代码中实现逻辑来完成。以下是一个 Node.js Express 服务器端的示例代码： const express = require(&#39;express&#39;); const path = require(&#39;path&#39;); const app = express(); // 定义静态文件目录，这里假设打包后的前端文件在 public 目录下 app.use(express.static(path.join(__dirname, &#39;public&#39;))); // 定义路由，根据路径名返回不同的 HTML 页面 app.get(&#39;/&#39;, (req, res) =&gt; { res.sendFile(path.join(__dirname, &#39;public&#39;, &#39;index.html&#39;)); }); app.get(&#39;/pageOffice&#39;, (req, res) =&gt; { res.sendFile(path.join(__dirname, &#39;public&#39;, &#39;pageOffice.html&#39;)); }); // 启动服务器 const PORT = process.env.PORT || 3000; app.listen(PORT, () =&gt; { console.log(<code>Server is running on port ${PORT}</code>); }); 在这个示例中，我们通过 Express 框架创建了一个简单的服务器。根据不同的路径，服务器会返回不同的 HTML 页面。因此，你可以在对应的 HTML 页面中根据需要加载不同的 JavaScript 文件。 例如，在根目录下的 index.html 文件中可以只加载通用的 JavaScript 文件，而在 pageOffice.html 文件中可以加载特定的 JavaScript 文件。 这种方法可以灵活地根据路径名加载不同的 JavaScript 文件，适用于已经预先打包好的前端文件。</p></div>',1)])])}const h=t(s,[["render",o]]);export{u as __pageData,h as default};
